<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DSWD MIMAROPA Kiosk</title><style>body{margin:0;font-family:Arial;background:linear-gradient(135deg,#e8f3ff,#f8fafc);color:#111827}.wrap{max-width:980px;margin:auto;padding:24px}.card{background:#fff;border-radius:24px;padding:24px;box-shadow:0 18px 45px #0002}h1{text-align:center;color:#00008b;margin:0 0 8px}.note{text-align:center;color:#64748b}.sec{background:#f8fafc;border:1px solid #d6dce8;border-radius:18px;padding:18px;margin-top:14px}.sec h2{margin:0 0 12px;color:#0f2f56;font-size:18px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.f{display:flex;flex-direction:column}.f label{font-size:13px;font-weight:900;margin-bottom:6px}.f input,.f select{height:48px;border:1px solid #cbd5e1;border-radius:12px;padding:0 12px;font-size:15px;background:white}.f select:disabled{background:#e5e7eb}.two{grid-column:span 2}.buttons{display:flex;flex-direction:column;gap:12px}.assist{height:74px;border-radius:999px;border:4px solid #08b7e5;background:linear-gradient(#fff,#dce5e8);box-shadow:5px 7px 0 #0003;font-size:23px;font-weight:1000;text-align:left;padding-left:42px;cursor:pointer}.assist:hover{transform:translateY(-2px);background:#eef9ff}.assist:disabled{opacity:.55;cursor:not-allowed}.status{text-align:center;font-weight:900;min-height:30px;margin-top:12px;color:#0f766e}.err{color:#dc2626}.result{display:none;text-align:center;background:#eff6ff;border:1px solid #bfdbfe;border-radius:18px;padding:20px;margin-top:14px}.queue{font-size:56px;font-weight:1000;color:#00008b}.btn{border:0;border-radius:999px;padding:13px 22px;font-weight:900;cursor:pointer;margin:5px}.print{background:#16a34a;color:white}.again{background:#0b2e83;color:white}.stubwrap{display:none}.stub{width:80mm;max-width:80mm;margin:0 auto;padding:8mm 6mm;background:#fff}.stub h2{text-align:center;margin:0 0 6px}.row{display:flex;justify-content:space-between;border-bottom:1px dotted #aaa;font-size:12px;padding:5px 0;gap:10px}.row b{text-align:right}@media(max-width:760px){.grid{grid-template-columns:1fr}.two{grid-column:span 1}.assist{font-size:18px;padding-left:25px}}@media print{.wrap{display:none}.stubwrap{display:block}@page{size:80mm auto;margin:0}}</style></head><body><div class="wrap"><div class="card"><h1>DSWD MIMAROPA Registration Kiosk</h1><p class="note">Fill in details, choose address from dropdowns, then tap assistance type.</p><div class="sec"><h2>Beneficiary Information</h2><div class="grid"><div class="f"><label>First Name *</label><input id="firstName"></div><div class="f"><label>Middle Name</label><input id="middleName"></div><div class="f"><label>Last Name *</label><input id="lastName"></div><div class="f"><label>Ext. Name</label><input id="extName"></div><div class="f two"><label>Contact Number *</label><input id="contactNumber" placeholder="09XXXXXXXXX or +639XXXXXXXXX" maxlength="13"></div></div></div><div class="sec"><h2>Complete Address - MIMAROPA Only</h2><div class="grid"><div class="f"><label>Province *</label><select id="province" onchange="loadCities()"><option value="">Loading...</option></select></div><div class="f"><label>City / Municipality *</label><select id="city" onchange="loadBarangays()" disabled><option value="">Select city</option></select></div><div class="f"><label>Barangay *</label><select id="barangay" disabled><option value="">Select barangay</option></select></div><div class="f"><label>House No. / Street / Sitio *</label><input id="street"></div></div></div><div class="sec"><h2>Select Assistance Type</h2><div class="buttons"><button class="assist" onclick="generateQueue('Medical Assistance')">Medical Assistance</button><button class="assist" onclick="generateQueue('Funeral Assistance')">Funeral Assistance</button><button class="assist" onclick="generateQueue('Educational Assistance')">Educational Assistance</button><button class="assist" onclick="generateQueue('Transportation Assistance')">Transportation Assistance</button><button class="assist" onclick="generateQueue('Material Assistance')">Material Assistance</button><button class="assist" onclick="generateQueue('Food Assistance')">Food Assistance</button><button class="assist" onclick="generateQueue('Cash Relief Assistance')">Cash Relief Assistance</button></div><div id="status" class="status"></div></div><div id="result" class="result"><h2>Queue Generated</h2><div id="queueNo" class="queue">-</div><p id="summary"></p><button class="btn print" onclick="printStub()">Print Stub</button><button class="btn again" onclick="resetScreen()">New Queue</button></div></div></div><div class="stubwrap"><div class="stub"><h2>DSWD QUEUE STUB</h2><div class="row"><span>Queue Number</span><b id="stubQueue">-</b></div><div class="row"><span>Code</span><b id="stubCode">-</b></div><div class="row"><span>Name</span><b id="stubName">-</b></div><div class="row"><span>Contact</span><b id="stubContact">-</b></div><div class="row"><span>Assistance</span><b id="stubProgram">-</b></div><div class="row"><span>Address</span><b id="stubAddress">-</b></div><div class="row"><span>Date</span><b id="stubDate">-</b></div></div></div><script>const RC='170000000';let pc='',cc='',lastQueue=null;const province=document.getElementById('province'),city=document.getElementById('city'),barangay=document.getElementById('barangay');function msg(x,b=false){status.className='status'+(b?' err':'');status.textContent=x}async function api(p){let r=await fetch('../api/psgc.php?'+new URLSearchParams(p),{cache:'no-store'}),d=await r.json();if(!d.success)throw Error(d.message||'Address list unavailable');return d.items||[]}function fill(s,a,t){s.innerHTML='<option value="">'+t+'</option>';a.forEach(x=>{let o=new Option(x.name,x.name);o.dataset.code=x.code;s.add(o)});s.disabled=false}async function init(){try{msg('Loading address list...');let p=await api({type:'provinces',region_code:RC});p.push({name:'Independent City / No Province',code:'REGION_CITIES'});fill(province,p,'Select province/location');msg('Ready.')}catch(e){msg(e.message,true)}}async function loadCities(){pc=province.selectedOptions[0]?.dataset.code||'';cc='';city.innerHTML='<option value="">Select city</option>';barangay.innerHTML='<option value="">Select barangay</option>';city.disabled=true;barangay.disabled=true;if(!pc)return;try{msg('Loading cities...');let p=pc==='REGION_CITIES'?{type:'cities',region_code:RC}:{type:'cities',region_code:RC,province_code:pc};fill(city,await api(p),'Select city');msg('Ready.')}catch(e){msg(e.message,true)}}async function loadBarangays(){cc=city.selectedOptions[0]?.dataset.code||'';barangay.innerHTML='<option value="">Select barangay</option>';barangay.disabled=true;if(!cc)return;try{msg('Loading barangays...');fill(barangay,await api({type:'barangays',region_code:RC,province_code:pc==='REGION_CITIES'?'':pc,city_code:cc}),'Select barangay');msg('Ready.')}catch(e){msg(e.message,true)}}function v(id){return document.getElementById(id).value.trim()}function okPhone(x){return /^09\d{9}$/.test(x)||/^\+639\d{9}$/.test(x)||/^639\d{9}$/.test(x)}function validate(){if(!v('firstName')||!v('lastName'))return'Please enter first name and last name.';if(!okPhone(v('contactNumber')))return'Please enter a valid contact number.';if(!v('province')||!v('city')||!v('barangay')||!v('street'))return'Please complete all address dropdowns and street field.';return''}function lock(x){document.querySelectorAll('.assist').forEach(b=>b.disabled=x)}async function generateQueue(program){let e=validate();if(e){msg(e,true);return}msg('Checking duplicate records and generating queue...');lock(true);try{let body={first_name:v('firstName'),middle_name:v('middleName'),last_name:v('lastName'),ext_name:v('extName'),contact_number:v('contactNumber'),province:v('province'),city_municipality:v('city'),barangay:v('barangay'),street_address:v('street'),program_type:program};let r=await fetch('../api/kiosk_generate_queue.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!d.success)throw Error(d.message||'Unable to generate queue');lastQueue=d;queueNo.textContent=d.queue_number;summary.textContent=d.client_name+' - '+d.program_type+' - MIMAROPA';setStub(d);result.style.display='block';msg('Queue number ready. You may print the stub.')}catch(x){msg(x.message,true)}finally{lock(false)}}function setStub(d){stubQueue.textContent=d.queue_number||'-';stubCode.textContent=d.beneficiary_code||'-';stubName.textContent=d.client_name||'-';stubContact.textContent=d.contact_number||'-';stubProgram.textContent=d.program_type||'-';stubAddress.textContent=d.address||'-';stubDate.textContent=d.date_time||new Date().toLocaleString()}function printStub(){if(lastQueue)setStub(lastQueue);setTimeout(()=>print(),80)}function resetScreen(){lastQueue=null;result.style.display='none';msg('');['firstName','middleName','lastName','extName','contactNumber','street'].forEach(id=>document.getElementById(id).value='');province.value='';loadCities()}init();</script></body></html>